{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `MapleMonk.zouk_pandl_intermediate` AS WITH daily_store_costs AS ( SELECT date_generated AS cost_date, UPPER(store) as Store, lower(type) AS cost_type, CASE WHEN lower(Commission_Type) LIKE \'%percent%\' THEN CAST(REPLACE(REPLACE(Actual_Value, \'%\', \'\'),\",\",\"\") AS FLOAT64) / 100 ELSE NULL END AS commission_percent, CASE WHEN lower(Commission_Type) NOT LIKE \'%percent%\' THEN CAST(REPLACE(REPLACE(Actual_Value, \'%\', \'\'),\",\",\"\") AS FLOAT64) / (DATE_DIFF( PARSE_DATE(\'%d-%b-%y\', END_DATE), PARSE_DATE(\'%d-%b-%y\', START_DATE), DAY ) + 1) ELSE NULL END AS daily_fixed_value FROM MapleMonk.zouk_db_OFFLINE_STORE_COSTS, UNNEST(GENERATE_DATE_ARRAY( PARSE_DATE(\'%d-%b-%y\', START_DATE), PARSE_DATE(\'%d-%b-%y\', END_DATE) )) AS date_generated ), cte as ( select coalesce(ORDER_DATE,Invoice_Date,marketing_nocategory_date,marketing_date,store_rent.cost_date,store_cam.cost_date ,store_elec.cost_date,store_int.cost_date,store_hvac.cost_date,store_other.cost_date,store_salary.cost_date,store_incentive.cost_date,store_bank.cost_date) as Date_pre ,coalesce(sc.MARKETPLACE,case when lower(sc.source) like \'%shoppers%\' then \'SHOPPERSSTOP\' when lower(sc.source) like \'%chennai_silk%\' then \'THE_CHENNAI_SILK\' end, case when lower(coalesce(store_rent.store,store_cam.store,store_elec.store,store_int.store,store_hvac.store, store_other.store,store_salary.sTORE,store_incentive.store,store_bank.store)) like \'%shopper%\' then \'SHOPPERSSTOP\' when lower(coalesce(store_rent.store,store_cam.store,store_elec.store,store_int.store,store_hvac.store, store_other.store,store_salary.sTORE,store_incentive.store,store_bank.store)) like \'%chennai_silk%\' then \'THE_CHENNAI_SILK\' ELSE \'SHOPIFY POS\' end) as MARKETPLACE_pre ,coalesce( FINAL_MARKETPLACE, case when lower(coalesce(msc.marketing_channel,mscc.marketing_nocategory_channel)) like \'%amazon%\' then \'AMAZON\' when lower(coalesce(msc.marketing_channel,mscc.marketing_nocategory_channel)) like any (\'%google%\',\'%facebook%\') then \'website\' else lower(coalesce(msc.marketing_channel,mscc.marketing_nocategory_channel)) end , case when coalesce(store_rent.store,store_cam.store,store_elec.store,store_int.store,store_hvac.store, store_other.store,store_salary.sTORE,store_incentive.store,store_bank.store) is not null then \'EBO\' end) as FINAL_MARKETPLACE_pre ,coalesce(CHANNEL,msc.marketing_channel,mscc.marketing_nocategory_channel) channel_pre ,upper(coalesce(SOURCE,store_rent.store,store_cam.store,store_elec.store,store_int.store,store_hvac.store,store_other.store ,store_salary.sTORE,store_incentive.store,store_bank.store)) SOURCE ,REFERENCE_CODE ,sc.Discount_Codes ,sc.Coupon_Source ,sc.Source_Type ,CASE WHEN coalesce(store_rent.store,store_cam.store,store_elec.store,store_int.store,store_hvac.store, store_other.store,store_salary.sTORE,store_incentive.store,store_bank.store) is not null then \'OFFLINE\' ELSE sc.Marketplace_Segment end as marketplace_segment_pre ,Mode_Of_Business1 ,Mode_Of_Business2 ,CASE WHEN coalesce(store_rent.store,store_cam.store,store_elec.store,store_int.store,store_hvac.store, store_other.store,store_salary.sTORE,store_incentive.store,store_bank.store) is not null then \'EBO - STORES\' ELSE Upper(Grouped_Channel) END as Grouped_Channel ,new_customer_flag ,customer_id_final ,Invoice_Code ,coalesce(fsm.Brand,ofsm.Brand) AS Brand ,SKU ,sc.COMMONSKU ,upper(coalesce(PRODUCT_CATEGORY,msc.category)) as CATEGORY_PRE ,PRODUCT_SUB_CATEGORY ,sc.PRODUCT_TYPE ,upper(coalesce(sc.COLLECTION,msc.collection,mscc.collection)) as collection_pre ,sc.PRINT ,sc.Shipping_Type ,coalesce(sc.child_category_code, sc.category_code)category_code ,sc.UTM_Source ,sc.UTM_Campaign ,sc.UTM_Medium ,sc.Journey_Time ,SALEORDERITEMCODE ,ifnull((sc.BAU_MRP_ONLINE),0) BAU_MRP_SALES ,(ifnull(SELLING_PRICE,0)) SALES ,ifnull(case when tm.marketplace is not null then ( (case when ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) >= (ifnull(SELLING_PRICE,0)) then ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) - (ifnull(SELLING_PRICE,0)) else 0 end)) else 0 end,0) as bau_discount1 ,ifnull((ifnull(mc.commission_value,0) * ifnull(selling_price,0)),0) as muntr_sor ,ifnull(case when tm.marketplace is not null then ( (case when ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) >= (ifnull(SELLING_PRICE,0)) then ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) - (ifnull(SELLING_PRICE,0)) else 0 end)) else 0 end,0) + ( (ifnull((ifnull(ccogs.commission_value,0) * ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0)),0)) + ifnull((safe_divide(ifnull(ccogs.actual_value,0), count(*) over(partition by ccogs.start_date,ccogs.end_date,lower(ccogs.MARKETPLACE)))),0) ) as TRADE_MARGIN ,(ifnull((ifnull(ccogs.commission_value,0) * ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0)),0)) + ifnull((safe_divide(ifnull(ccogs.actual_value,0), count(*) over(partition by ccogs.start_date,ccogs.end_date,lower(ccogs.MARKETPLACE)))),0) as CCOGS ,case when tm.marketplace is null then ( (case when ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) >= (ifnull(SELLING_PRICE,0)) then ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) - (ifnull(SELLING_PRICE,0)) else 0 end)) else 0 end BAU_DISCOUNT ,(coalesce(ofsm.tax_rate,fsm.tax_rate,case when order_date < \'2025-09-22\' then 0.12 else 0.05 end) * (ifnull(SELLING_PRICE,0) - ifnull((RS.commission_value * ifnull(selling_price,0)),0))) /(1+coalesce(ofsm.tax_rate,fsm.tax_rate,case when order_date < \'2025-09-22\' then 0.12 else 0.05 end)) as GST ,(cm.commission_value * ifnull(selling_price,0)) CHANNEL_MARGIN ,case when (ifnull(RS.commission_value,0) * ifnull(selling_price,0)) = 0 then safe_divide(RS.Actual_value,count(*)over(partition by last_day(coalesce(order_date,rs.start_date)),lower(coalesce(sc.marketplace,rs.marketplace)))) else (RS.commission_value * ifnull(selling_price,0)) end as RETURNS ,case when (ifnull(lc.commission_value,0) * (case when tm.marketplace is not null then ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) else ifnull(selling_price,0) end)) = 0 then safe_divide(lc.Actual_value,count(*)over(partition by last_day(coalesce(order_date,lc.start_date)),lower(coalesce(sc.marketplace,lc.marketplace)))) else (lc.commission_value * (case when tm.marketplace is not null then ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) else ifnull(selling_price,0) end) ) end as LOGISTICS_COST ,ifnull(SC.quantity,0) Quantity ,(ifnull(resolved_cogs.resolved_cogs, 0) * ifnull(quantity,0)) - ifnull( case when cm.MARKETPLACE is not null then rs.commission_value * (ifnull(resolved_cogs.resolved_cogs, 0) * ifnull(quantity,0)) end,0) as cogs ,(ifnull(resolved_cogs.resolved_cogs, 0) * ifnull(quantity,0)) as initial_cogs ,IFNULL( store_rent.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store)) ) ), store_rent.daily_fixed_value ) + IFNULL(store_rent.commission_percent * IFNULL(selling_price, 0), 0) AS store_rent, IFNULL( store_cam.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE,store_rent.store, store_cam.store)) ) ), store_cam.daily_fixed_value ) + IFNULL(store_cam.commission_percent * IFNULL(selling_price, 0), 0) AS store_cam, IFNULL( store_elec.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store)) ) ), store_elec.daily_fixed_value ) + IFNULL(store_elec.commission_percent * IFNULL(selling_price, 0), 0) AS store_elec, IFNULL( store_int.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store)) ) ), store_int.daily_fixed_value ) + IFNULL(store_int.commission_percent * IFNULL(selling_price, 0), 0) AS store_int, IFNULL( store_hvac.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store)) ) ), store_hvac.daily_fixed_value ) + IFNULL(store_hvac.commission_percent * IFNULL(selling_price, 0), 0) AS store_hvac, IFNULL( store_other.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store,store_other.store)) ) ), store_other.daily_fixed_value ) + IFNULL(store_other.commission_percent * IFNULL(selling_price, 0), 0) AS store_other, IFNULL( store_salary.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store,store_other.store, store_salary.store)) ) ), store_salary.daily_fixed_value ) + IFNULL(store_salary.commission_percent * IFNULL(selling_price, 0), 0) AS store_salary, IFNULL( store_incentive.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store, store_salary.store, store_incentive.store)) ) ), 0 ) + IFNULL(store_incentive.commission_percent * IFNULL(selling_price, 0), 0) AS store_incentive, IFNULL( store_bank.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store, store_salary.store, store_bank.store)) ) ), 0 ) + IFNULL(store_bank.commission_percent * IFNULL(selling_price, 0), 0) AS store_bank, store_revenue.commission_percent as store_revenue_Share from ( select sc.* ,coalesce((ifnull(SELLING_PRICE,0)) / (1-tm.commission_value) ,GREATEST(ifnull(BAU_ONLINE,0),ifnull(SELLING_PRICE,0))) as BAU_MRP_ONLINE , CASE WHEN lower(sc.data_source) like \'%unicommerce%\' THEN UPPER(TRIM(sc.sku)) ELSE UPPER(TRIM(sc.commonsku)) END AS cogs_join_key ,CASE WHEN lower(sc.data_source) like \'%unicommerce%\' THEN \'child\' ELSE \'parent\' END AS cogs_path from maplemonk.zouk_sales_consolidated sc left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,MARKETPLACE ,cast(replace(ifnull(commission_value,\'0\'),\'%\',\'\') as float64)/100 as commission_value ,cast(Actual_Value as float64) as Actual_Value from MapleMonk.zouk_db_Marketplace_Commissions where upper(PANDL_CATEGORY) = \'TRADE MARGIN\' qualify row_number() over(partition by START_DATE,END_DATE,lower(marketplace) order by 1) = 1 ) tm on cast(ORDER_DATE as date) >= cast(tm.START_DATE as date) and cast(ORDER_DATE as date) <= cast(tm.END_DATE as date) and lower(sc.marketplace) = lower(tm.MARKETPLACE) where not(lower(ifnull(ORDER_STATUS,\'\')) like \'%cancel%\' or lower(ifnull(FINAL_SHIPPING_STATUS,\'\')) like \'%cancel%\') ) SC left join ( select distinct upper(MARKETPLACE) MARKETPLACE from MapleMonk.zouk_db_Marketplace