commonsku) = lower(ifnull(sc.commonsku,\'\')) and order_date >= \'2025-09-22\' left join (Select * from ( select *,row_number() over(partition by lower(ifnull(commonsku,\'\')) order by 1)rw from `MapleMonk.FINAL_SKU_MASTER_TEMP` )where rw = 1 ) ofsm on lower(ofsm.commonsku) = lower(ifnull(sc.commonsku,\'\')) and order_date < \'2025-09-22\' left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,MARKETPLACE ,PANDL_CATEGORY ,cast(replace(commission_value,\'%\',\'\') as float64)/100 as commission_value ,cast(Actual_Value as float64) as Actual_Value from(select *,row_number() over(partition by START_DATE,END_DATE,lower(MARKETPLACE) order by 1)rw from MapleMonk.zouk_db_Marketplace_Commissions) where upper(PANDL_CATEGORY) = \'CHANNEL MARGIN\' and rw =1 )cm on cast(ORDER_DATE as date) >= cast(cm.START_DATE as date) and cast(ORDER_DATE as date) <= cast(cm.END_DATE as date) and lower(sc.marketplace) = lower(cm.MARKETPLACE) left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,MARKETPLACE ,cast(replace(Estimated_Return_Share,\'%\',\'\') as float64)/100 as commission_value ,cast(Actual_Return_Value as float64) as Actual_Value from MapleMonk.zouk_db_returns_share )rs on cast(ORDER_DATE as date) >= cast(rs.START_DATE as date) and cast(ORDER_DATE as date) <= cast(rs.END_DATE as date) and lower(sc.marketplace) = lower(rs.MARKETPLACE) left join ( SELECT join_sku, START_DATE, END_DATE, path, resolved_cogs, ROW_NUMBER() OVER ( PARTITION BY join_sku, START_DATE, END_DATE ORDER BY CASE WHEN path = \'child\' THEN 1 ELSE 2 END ) AS path_priority FROM ( SELECT child_sku AS join_sku, START_DATE, END_DATE, \'child\' AS path, child_cogs AS resolved_cogs, ROW_NUMBER() OVER ( PARTITION BY child_sku, START_DATE, END_DATE ORDER BY parent_sku ) AS rn FROM `MapleMonk.Zouk_sku_Level_cogs` WHERE is_bundle = true UNION ALL SELECT parent_sku AS join_sku, START_DATE, END_DATE, \'parent\' AS path, cogs AS resolved_cogs, 1 AS rn FROM `MapleMonk.Zouk_sku_Level_cogs_parent` ) WHERE rn = 1 QUALIFY path_priority = 1 ) resolved_cogs ON cast(sc.ORDER_DATE as date) >= resolved_cogs.START_DATE AND cast(sc.ORDER_DATE as date) <= resolved_cogs.END_DATE AND UPPER(TRIM(sc.cogs_join_key)) = resolved_cogs.join_sku Full Outer join ( select cast(null as date) as marketing_date ,cast(null as string) as marketing_channel ,cast(null as string) category ,cast(null as string) collection ,0 as spend ,0 as Brand_Spend ,0 as Meta_1D_Conversions ,0 as Meta_1D_Conversions_Value from maplemonk.zouk_MARKETING_CONSOLIDATED limit 0 )msc on cast(msc.marketing_date as date) = cast(sc.order_Date as date) and lower(msc.marketing_channel) = lower(sc.channel) and lower(sc.PRODUCT_CATEGORY) = lower(msc.category) Full Outer join ( select cast(null as date) as marketing_nocategory_date ,cast(null as string) as marketing_nocategory_channel ,cast(null as string) collection ,0 as spend ,0 as Brand_Spend ,0 as Meta_1D_Conversions ,0 as Meta_1D_Conversions_Value from maplemonk.zouk_MARKETING_CONSOLIDATED limit 0 )mscc on cast(mscc.marketing_nocategory_date as date) = coalesce(cast(sc.order_Date as date),cast(msc.marketing_date as date)) and lower(mscc.marketing_nocategory_channel) = coalesce(lower(sc.channel),lower(msc.marketing_channel)) and lower(sc.collection) = lower(mscc.collection) FULL OUTER JOIN ( SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_store_costs WHERE cost_type = \'rent\' ) store_rent ON CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE) = store_rent.cost_date AND lower(sc.source) = lower(store_rent.store) FULL OUTER JOIN ( SELECT cost_date, store, commission_percent, daily_fixed_value FROM daily_store_costs WHERE cost_type LIKE \'%cam charges%\' ) store_cam ON CAST(COALESCE(ORDER_DATE, marketing_date, marketing_nocategory_date, store_rent.cost_date) AS DATE) = store_cam.cost_date AND lower(COALESCE(SOURCE, store_rent.store)) =